import {ROSTER,SKILLS,getCharacter,buildLabel} from './roster.js';
export function setupRosterUI(onChoose,initial){for(const [role,key]of [['human','humanPlayer'],['computer','computerPlayer']]){const select=document.querySelector('#'+key);for(const p of [...ROSTER].sort((a,b)=>b.average-a.average)){const o=document.createElement('option');o.value=p.id;o.textContent=`${p.name} · ${p.average}`;select.append(o);}select.value=initial[role];const render=()=>{const p=getCharacter(select.value),card=document.querySelector('#'+role+'Card');card.querySelector('.roster-build').textContent=buildLabel(p)+(p.hat?' · cap':'');card.querySelector('.roster-average').textContent=p.average+' average';const avatar=card.querySelector('.roster-avatar');avatar.style.setProperty('--skin',p.skin);avatar.style.setProperty('--hair',p.hair);avatar.style.setProperty('--band',p.hat?p.hatColor:p.band);avatar.classList.toggle('has-cap',p.hat);const grid=card.querySelector('.skill-grid');grid.replaceChildren();for(const [k,label]of Object.entries(SKILLS)){const row=document.createElement('div'),name=document.createElement('span'),value=document.createElement('b'),bar=document.createElement('meter');name.textContent=label;value.textContent=p.ratings[k];bar.min=1;bar.max=100;bar.value=p.ratings[k];bar.setAttribute('aria-label',label+' '+p.ratings[k]+' out of 100');row.append(name,value,bar);grid.append(row);}return p;};render();select.addEventListener('change',()=>onChoose(role,render()));}}
